18	/**
19	 * SovereignTrainingHUD
20	 *
21	 * The Semantic Layer of the Sovereign Training Ground.
22	 * Renders floating, pedagogy-enriched labels for entities.
23	 */
24	export const SovereignTrainingHUD: React.FC = () => {
25	    const [hoveredEntity, setHoveredEntity] = useState<EntityHUDData | null>(null);
26	    const [overlayElement, setOverlayElement] = useState<HTMLDivElement | null>(null);
27	
28	    useEffect(() => {
29	        // Initialize CSS2D Renderer for the HUD
30	        const scene = (window as any).rsmvScene; // Assume scene is exposed globally by rsmv_inspector
31	        if (!scene) return;
32	
33	        const width = window.innerWidth;
34	        const height = window.innerHeight;
35	
36	        const labelRenderer = new CSS2DRenderer();
37	        labelRenderer.setSize(width, height);
38	        labelRenderer.domElement.style.position = 'absolute';
39	        labelRenderer.domElement.style.top = '0px';
40	        labelRenderer.domElement.style.pointerEvents = 'none';
41	        document.body.appendChild(labelRenderer.domElement);
42	
43	        const raycaster = new THREE.Raycaster();
44	        const mouse = new THREE.Vector2();
45	
46	        const onMouseMove = (event: MouseEvent) => {
47	            mouse.x = (event.clientX / width) * 2 - 1;
48	            mouse.y = -(event.clientY / height) * 2 + 1;
49	
50	            raycaster.setFromCamera(mouse, (window as any).rsmvCamera);
51	            const intersects = raycaster.intersectObjects(scene.children, true);
52	
53	            if (intersects.length > 0) {
54	                const obj = intersects[0].object;
55	                // The SovereignObjectRenderer tags meshes with a unique key like "LOC_123"
56	                const idMatch = obj.name?.match(/LOC_(\d+)|NPC_(\d+)/);
57	                if (idMatch) {
58	                    const entityId = idMatch[1] || idMatch[2];
59	                    fetchSovereignData(entityId);
60	                }
61	            } else {
62	                setHoveredEntity(null);
63	            }
64	        };
65	
66	        window.addEventListener('mousemove', onMouseMove);
67	
68	        // Animation loop for HUD labels
69	        const animate = () => {
70	            labelRenderer.render((window as any).rsmvScene, (window as any).rsmvCamera);
71	            requestAnimationFrame(animate);
72	        };
73	        animate();
74	
75	        return () => {
76	            window.removeEventListener('mousemove', onMouseMove);
77	            document.body.removeChild(labelRenderer.domElement);
78	        };
79	    }, []);
80	
81	    const fetchSovereignData = async (entityId: string) => {
82	        // Request pedagogy-enriched data via the Sovereign Bridge
83	        const bridge = SovereignBridge.getInstance();
84	
85	        // We send a REQUEST_PEDAGOGY signal to the server
86	        bridge.send({
87	            type: 'REQUEST_PEDAGOGY',
88	            entityId: entityId,
89	            context: 'HUD_HOVER'
90	        });
91	
92	        // The response comes back via the ENTITY channel
93	        // We'll listen for it in a separate useEffect or via a bridge callback
94	    };
95	
96	    // Handle incoming ENTITY packets from SovereignBridge
97	    useEffect(() => {
98	        const bridge = SovereignBridge.getInstance();
99	        bridge.on('ENTITY_DATA', (data: EntityHUDData) => {
100	            setHoveredEntity(data);
101	        });
102	    }, []);
103	
104	    if (!hoveredEntity) return null;
105	
106	    return (
107	        <div style={{
108	            position: 'absolute',
109	            bottom: '20px',
110	            right: '20px',
111	            backgroundColor: 'rgba(0, 0, 0, 0.8)',
112	            color: '#00ffff',
113	            padding: '15px',
114	            borderRadius: '8px',
115	            fontFamily: 'monospace',
116	            border: '1px solid #00ffff',
117	            pointerEvents: 'none',
118	            zIndex: 1000,
119	            minWidth: '250px'
120	        }}>
121	            <div style={{ fontSize: '1.2em', fontWeight: 'bold', marginBottom: '5px' }}>
122	                {hoveredEntity.name}
123	            </div>
124	            <div style={{ fontSize: '0.8em', color: '#aaa', marginBottom: '10px' }}>
125	                ID: {hoveredEntity.sovereignId} | Type: {hoveredEntity.type.toUpperCase()}
126	            </div>
127	
128	            <div style={{ borderTop: '1px solid #333', paddingTop: '10px' }}>
129	                <div style={{ fontSize: '0.9em', color: '#fff' }}>
130	                    <strong>Pedagogy Grounding:</strong>
131	                </div>
132	                {hoveredEntity.stats.requirements && Object.entries(hoveredEntity.stats.requirements).map(([skill, level]) => (
133	                    <div key={skill} style={{ fontSize: '0.8em' }}>
134	                        {skill}: {level}
135	                    </div>
136	                ))}
137	                {hoveredEntity.stats.combat && (
138	                    <div style={{ fontSize: '0.8em' }}>Combat Rating: {hoveredEntity.stats.combat}</div>
139	                )}
140	            </div>
141	
142	            <div style={{ marginTop: '10px', display: 'flex', gap: '5px', flexWrap: 'wrap' }}>
143	                {hoveredEntity.actionables.map(act => (
144	                    <span key={act} style={{
145	                        backgroundColor: '#004444',
146	                        padding: '2px 6px',
147	                        fontSize: '0.7em',
148	                        borderRadius: '4px',
149	                        border: '1px solid #00ffff'
150	                    }}>
151	                        {act}
152	                    </span>
153	                ))}
154	            </div>
155	        </div>
156	    );
157	};
