8	// ── Authentic Anchor Registry ──────────────────────────────────────
9	const AUTHENTIC_ANCHORS = new Set([
10	  'Banker', 'Bank booth', 'Guard', 'General Store assistant',
11	  'Shop assistant', 'Shop keeper', 'Grand Exchange clerk',
12	  'Fairy ring', 'Spirit tree', 'Lodestone', 'Portal',
