16	// ── Vocabulary Frequency Map ────────────────────────────────────────
17	const VOCAB_MAP: Map<string, number> = new Map(
18	  (interactionVocabulary.actions as [string, number][])
19	    .map(([action, freq]) => [action.toLowerCase(), freq])
