53	export interface EntityHUDData {
54	    name: string;
55	    type: 'npc' | 'item' | 'object' | 'loc';
56	    sovereignId: string;
57	    stats: {
58	        combat?: number;
59	        level?: number;
60	        requirements?: Record<string, number>;
61	        degradation?: { charges: number; max: number };
62	    };
63	    actionables: Array<{
64	        action: string;
65	        requirements: string[];
66	        effect: string;
67	    }>;
68	    pedagogy: {
69	        description: string;
70	        examine: string;
71	    };
72	    emotionalWeight: Record<string, number>;
73	    hexagramPin: {
74	        id: number;
75	        name: string;
76	        line: number;
77	    };
78	}
