80	/**
81	 * SovereignEntityResolver
82	 *
83	 * Bridges raw entity IDs to the "Sovereign Truth" (Manifests) and
84	 * "Cached Truth" (R2/KV mirror of the game cache).
85	 *
86	 * Refactored for DO compatibility:
87	 * 1. No subprocesses (spawn).
88	 * 2. No local filesystem (fs).
89	 * 3. Uses bundled JSON for manifest and environment bindings for cache data.
90	 */
91	export class SovereignEntityResolver {
92	    private static instance: SovereignEntityResolver;
93	    private manifest: Manifest;
94	    private env: any = null;
95	
96	    public static getInstance(): SovereignEntityResolver {
97	        if (!SovereignEntityResolver.instance) {
98	            SovereignEntityResolver.instance = new SovereignEntityResolver();
99	        }
100	        return SovereignEntityResolver.instance;
101	    }
102	
103	    private constructor() {
104	        this.manifest = manifestData;
105	        logger.info(`Sovereign Manifest Initialized: ${this.manifest.entities.length} entities grounded.`);
106	    }
107	
108	    /**
109	     * initialize - Binds the Durable Object environment (KV, R2).
110	     */
111	    public initialize(env: any): void {
112	        this.env = env;
113	        logger.info('SovereignEntityResolver bound to DO environment.');
114	    }
115	
116	    /**
117	     * resolve - Maps a raw entityId to a high-fidelity HUD data object.
118	     */
119	    public async resolve(entityId: number): Promise<Result<EntityHUDData>> {
120	        // 1. Find Ground Truth in bundled manifest
121	        const truth = this.manifest.entities.find(e => e.entityId === entityId);
122	
123	        // 2. Fetch raw cache la-Sovereign data from the environment (R2/KV)
124	        // In a DO, we no longer call a subprocess. We fetch pre-extracted JSON dumps.
125	        const rawData = await this.fetchRawCacheData(entityId);
126	
127	        // 3. Map to HUD format
128	        const type = this.determineType(rawData);
129	        return ok(this.mapToHUD(rawData, type, truth, entityId));
130	    }
131	
132	    private async fetchRawCacheData(entityId: number): Promise<any> {
133	        if (!this.env || !this.env.SOVEREIGN_CACHE) {
134	            logger.warn('No cache binding found. Using empty raw data.');
135	            return {};
136	        }
137	
138	        try {
139	            // We assume the cache has been dumped to KV/R2 as "cache:npc:<id>", etc.
140	            // This is the "Sovereign Mirror" pattern.
141	            const data = await this.env.SOVEREIGN_CACHE.get(`entity:${entityId}`);
142	            return data ? JSON.parse(data) : {};
143	        } catch (e) {
144	            logger.error({ err: e }, `Failed to fetch cache data for ${entityId}`);
145	            return {};
146	        }
147	    }
148	
149	    private determineType(raw: any): EntityHUDData['type'] {
150	        if (raw.combatLevel !== undefined || raw.npc) return 'npc';
151	        if (raw.isEquippable || raw.equipSlotId !== undefined) return 'item';
152	        if (raw.sizeX !== undefined || raw.object) return 'object';
153	        return 'loc';
154	    }
155	
156	    private mapToHUD(raw: any, type: EntityHUDData['type'], truth: ManifestEntity | undefined, fallbackId?: number): EntityHUDData {
157	        const id = truth?.id || `S-${type.toUpperCase()}-${raw.id || fallbackId}`;
158	
159	        return {
160	            name: truth?.title || raw.name || `Entity ${fallbackId}`,
161	            type,
162	            sovereignId: id,
163	            stats: {
164	                combat: raw.combatLevel || 0,
165	                level: raw.combatLevel || 0,
166	                requirements: {}, // To be filled by PedagogyBridge
167	                degradation: this.parseDegradation(raw.extra)
168	            },
169	            actionables: (truth?.actions || raw.actions || []).map(act => ({
170	                action: act,
171	                requirements: this.inferRequirements(act, raw),
172	                effect: this.inferActionEffect(act)
173	            })),
174	            pedagogy: {
175	                description: truth?.meta?.description || 'No pedagogical grounding available.',
176	                examine: truth?.meta?.examine || 'Observation inconclusive.'
177	            },
178	            emotionalWeight: {}, // To be filled by PedagogyBridge
179	            hexagramPin: {
180	                id: 0,
181	                name: 'The Void',
182	                line: 0
183	            }
184	        };
185	    }
186	
187	    private parseDegradation(extra: any): { charges: number, max: number } {
188	        if (!extra || !Array.isArray(extra)) return { charges: 0, max: 0 };
189	
190	        const chargesProp = extra.find((e: any) => e.prop === 7479);
191	        const variantProp = extra.find((e: any) => e.prop === 7480);
192	
193	        const charges = chargesProp?.intvalue || 0;
194	
195	        let max = 100000; // Standard trimmed masterwork
196	        if (variantProp?.intvalue === 1) max = 200000; // Custom-fit
197	
198	        return { charges, max };
199	    }
200	
201	    private inferActionEffect(action: string): string {
202	        const lower = action.toLowerCase();
203	        if (lower.includes('attack') || lower.includes('strike')) return 'initiate_combat';
204	        if (lower.includes('talk') || lower.includes('chat')) return 'open_dialogue';
205	        if (lower.includes('pickpocket') || lower.includes('steal')) return 'attempt_thieving';
206	        if (lower.includes('capture')) return 'initiate_capture';
207	        if (lower.includes('check') || lower.includes('inspect')) return 'display_status';
208	        if (lower.includes('remove') || lower.includes('unequip')) return 'unequip_item';
209	        if (lower.includes('wield') || lower.includes('equip')) return 'equip_item';
210	        if (lower.includes('use') || lower.includes('activate')) return 'interact_object';
211	        if (lower.includes('examine') || lower.includes('look')) return 'perform_inspection';
212	        return 'generic_interaction';
213	    }
214	
215	    private inferRequirements(action: string, raw: any): string[] {
216	        const lower = action.toLowerCase();
217	        const reqs: string[] = [];
218	
219	        if (lower.includes('attack') || lower.includes('strike')) {
220	            if (raw.combatLevel) reqs.push(`combat >= ${raw.combatLevel}`);
221	        }
222	        if (lower.includes('wield') || lower.includes('equip')) {
223	            if (raw.combatLevel) reqs.push(`level >= ${raw.combatLevel}`);
224	        }
225	
226	        return reqs;
227	    }
228	}
