1	import { ModelClient } from '../clients/ModelClient.js';
2	import { Result, ok, err } from '../core/models.js';
3	import { createLogger } from '../utils/logger.js';
4	
5	const logger = createLogger('SovereignPedagogyBridge');
6	
7	export interface PedagogyEnrichment {
8	    learningNote: string;
9	    confidence: number;
10	    suggestedAction: {
11	        action: string;
12	        target: string;
13	        reasoning: string;
14	    };
15	    emotionalWeight: Record<string, number>;
16	    hexagramPin: {
17	        id: number;
18	        name: string;
19	        line: number;
20	    };
21	}
22	
23	/**
24	 * SovereignPedagogyBridge
25	 *
26	 * Interfaces with the pedagogy model to provide "AI-driven truth"
27	 * for entities that are missing from the physical manifests.
28	 *
29	 * Designed for DO compatibility: Environment-based and cache-aware.
30	 */
31	export class SovereignPedagogyBridge {
32	    private static instance: SovereignPedagogyBridge;
33	    private kv: any = null;
34	
35	    private constructor() {}
36	
37	    public static getInstance(): SovereignPedagogyBridge {
38	        if (!SovereignPedagogyBridge.instance) {
39	            SovereignPedagogyBridge.instance = new SovereignPedagogyBridge();
40	        }
41	        return SovereignPedagogyBridge.instance;
42	    }
43	
44	    /**
45	     * initialize - Explicitly binds the environment for the bridge.
46	     * Prevents the "late-binding footgun" of injectEnv.
47	     */
48	    public initialize(env: { KV?: any }): void {
49	        this.kv = env.KV;
50	        logger.info('SovereignPedagogyBridge bound to environment KV store.');
51	    }
52	
53	    /**
54	     * enrich - Uses the ModelClient to generate a pedagogical insight for an entity.
55	     */
56	    public async enrich(entityId: number, basicData: any, modelClient: ModelClient): Promise<Result<PedagogyEnrichment>> {
57	        const cacheKey = `pedagogy:${entityId}`;
58	
59	        // 1. KV Cache Lookup
60	        if (this.kv) {
61	            try {
62	                const cached = await this.kv.get(cacheKey);
63	                if (cached) return ok(JSON.parse(cached));
64	            } catch (e) {
65	                logger.warn({ err: e }, 'KV lookup failed, proceeding to inference.');
66	            }
67	        }
68	
69	        const prompt = this.buildPrompt(entityId, basicData);
70	
71	        // 2. Query Model with JSON format request
72	        // We use the la-Sovereign dispatch via ModelClient
73	        const res = await modelClient.call({
74	            model: modelClient.getRolodex()?.resolveCapability('pedagogy').model || 'deepseek-r1:8b',
75	            prompt,
76	            temperature: 0.3,
77	            format: 'json'
78	        });
79	
80	        if (!res.ok) return res as any;
81	
82	        try {
83	            const parsed = JSON.parse(res.value.response) as any;
84	            const validated = this.validateAndNormalize(parsed);
85	
86	            // 3. Cache result (1-hour TTL)
87	            if (this.kv) {
88	                await this.kv.put(cacheKey, JSON.stringify(validated), { expirationTtl: 3600 });
89	            }
90	
91	            return ok(validated);
92	        } catch (e) {
93	            return err(new Error(`Failed to parse and validate pedagogy response: ${e instanceof Error ? e.message : String(e)}`));
94	        }
95	    }
96	
97	    private buildPrompt(entityId: number, basicData: any): string {
98	        return `
99	Sovereign Pedagogy Audit
100	Entity ID: ${entityId}
101	Raw Data: ${JSON.stringify(basicData)}
102	
103	Provide a concise pedagogical insight into this entity.
104	Why does this entity exist in the context of the world's "Truth"?
105	What is its primary training value?
106	
107	Respond in JSON ONLY with the following schema:
108	{
109	    "learningNote": "string",
110	    "confidence": "number (0.0-1.0)",
111	    "suggestedAction": {
112	        "action": "string",
113	        "target": "string",
114	        "reasoning": "string"
115	    },
116	    "emotionalWeight": { "trait": "number(0.0-1.0)" },
117	    "hexagramPin": {
118	        "id": "number (1-64)",
119	        "name": "string",
120	        "line": "number (1-6)"
121	    }
122	}
123	`;
124	    }
125	
126	    private validateAndNormalize(raw: any): PedagogyEnrichment {
127	        return {
128	            learningNote: raw.learningNote || 'No pedagogical insight available.',
129	            confidence: Math.max(0, Math.min(1, raw.confidence || 0.5)),
130	            suggestedAction: {
131	                action: raw.suggestedAction?.action || 'Observe',
132	                target: raw.suggestedAction?.target || 'Entity',
133	                reasoning: raw.suggestedAction?.reasoning || 'Standard observation required.'
134	            },
135	            emotionalWeight: this.normalizeWeights(raw.emotionalWeight),
136	            hexagramPin: {
137	                id: Math.max(1, Math.min(64, raw.hexagramPin?.id || 1)),
138	                name: raw.hexagramPin?.name || 'The Void',
139	                line: Math.max(1, Math.min(6, raw.hexagramPin?.line || 1))
140	            }
141	        };
142	    }
143	
144	    private normalizeWeights(weights: any): Record<string, number> {
145	        const normalized: Record<string, number> = {};
146	        if (typeof weights !== 'object' || weights === null) return normalized;
147	
148	        for (const [k, v] of Object.entries(weights)) {
149	            const val = Number(v); // JSON.parse handles most, but Number() ensures cast
150	            normalized[k] = isNaN(val) ? 0 : Math.max(0, Math.min(1, val));
151	        }
152	        return normalized;
153	    }
154	}
