1	/**
2	 * SovereignBridge - Real-time WebSocket bridge to the POG2 Backend.
3	 * Decouples the 3D Viewer from the heavy POG2 Orchestrator while maintaining state parity.
4	 */
5	export class SovereignBridge {
6	    private static instance: SovereignBridge;
7	    private ws: WebSocket | null = null;
8	    private listeners: ((msg: any) => void)[] = [];
9	    private tickListeners: ((msg: any) => void)[] = [];
10	    private logListeners: ((log: any) => void)[] = [];
11	    private engine: any = null;
12	    private retryCount = 0;
13	    private state: any = {
14	        tick: 0,
15	        avatar: { x: 3200, y: 3200, plane: 0, username: 'POG2_Sovereign', isBusy: false },
16	        inventory: [],
17	        activeModule: 'idle'
18	    };
19	
20	    private constructor() {
21	        this.connect();
22	    }
23	
24	    public static getInstance(): SovereignBridge {
25	        if (!this.instance) {
26	            this.instance = new SovereignBridge();
27	        }
28	        return this.instance;
29	    }
30	
31	    private connect() {
32	        // POG2 Switchboard Default Port: 8789
33	        this.ws = new WebSocket('ws://localhost:8789');
34	
35	        this.ws.onopen = () => {
36	            this.retryCount = 0;
37	            console.log('%c[BRIDGE] Connected to Sovereign Switchboard', 'color: #00ff00; font-weight: bold;');
38	        };
39	
40	        this.ws.onmessage = (event) => {
41	            try {
42	                const msg = JSON.parse(event.data);
43	
44	                if (msg.type === 'state_sync') {
45	                    this.state = msg.state;
46	                    this.notifyListeners(msg);
47	
48	                } else if (msg.type === 'GAME_STATE') {
49	                    // syncGameState() on the server wraps state in payload:
50	                    const gs = msg.payload ?? msg;
51	                    // Normalize to the shape SovereignHUD expects from state_sync
52	                    const normalized = {
53	                        type: 'state_sync',
54	                        tick: msg.timestamp ?? Date.now(),
55	                        state: {
56	                            tick: msg.timestamp ?? Date.now(),
57	                            avatar: gs.avatar ?? this.state.avatar,
58	                            activeModule: gs.activeModule ?? this.state.activeModule
59	                        }
60	                    };
61	                    this.state = normalized.state;
62	                    this.notifyListeners(normalized);
63	
64	                } else if (msg.type === 'tick_event') {
65	                    this.notifyTickListeners(msg);
66	
67	                } else if (msg.type === 'ghost_splat') {
68	                    // SwitchboardLimb.broadcastGhostSplat wraps in payload:
69	                    const field = msg.payload ?? msg;
70	                    this.notifyTickListeners({ type: 'ghost_splat', field });
71	
72	                } else if (msg.type === 'kernel_diagnostics') {
73	                    // SwitchboardLimb.broadcastKernelDiagnostics wraps in payload:
74	                    const diag = msg.payload ?? msg;
75	                    this.notifyTickListeners({ type: 'kernel_diagnostics', ...diag });
76	
77	                } else if (msg.type === 'SYSTEM_LOG') {
78	                    this.notifyLogListeners(msg.payload);
79	
80	                } else if (msg.type === 'log') {
81	                    // console.debug('[POG2 LOG]', msg.message);
82	                }
83	            } catch (err) {
84	                console.error('[BRIDGE] Parse error:', err);
85	            }
86	        };
87	
88	        this.ws.onclose = () => {
89	            this.retryCount++;
90	            const delay = Math.min(5000 * Math.pow(2, this.retryCount - 1), 60000);
91	            if (this.retryCount <= 3) {
92	                console.warn(`[BRIDGE] Socket closed. Retry #${this.retryCount} in ${delay / 1000}s...`);
93	            }
94	            setTimeout(() => this.connect(), delay);
95	        };
96	
97	        this.ws.onerror = (err) => {
98	            // console.error('[BRIDGE] Socket error:', err);
99	        };
100	    }
101	
102	    public onSync(callback: (msg: any) => void) {
103	        this.listeners.push(callback);
104	    }
105	
106	    public onTick(callback: (msg: any) => void) {
107	        this.tickListeners.push(callback);
108	    }
109	
110	    public onSystemLog(callback: (log: any) => void) {
111	        this.logListeners.push(callback);
112	    }
113	
114	    private notifyListeners(msg: any) {
115	        this.listeners.forEach(l => l(msg));
116	    }
117	
118	    private notifyTickListeners(msg: any) {
119	        this.tickListeners.forEach(l => l(msg));
120	    }
121	
122	    private notifyLogListeners(log: any) {
123	        this.logListeners.forEach(l => l(log));
124	    }
125	
126	    public getState() {
127	        return this.state;
128	    }
129	
130	    public setEngine(engine: any) {
131	        this.engine = engine;
132	    }
133	
134	    /**
135	     * handleCommand - Clinical routing for the Sovereign Console.
136	     */
137	    public handleCommand(cmd: string) {
138	        const parts = cmd.trim().split(/\s+/);
139	        const command = parts[0].toLowerCase();
140	        const args = parts.slice(1);
141	
142	        this.log('CMD', 'User', `> ${cmd}`);
143	
144	        switch (command) {
145	            case '/tp':
146	            case '/teleport':
147	                if (args.length >= 2) {
148	                    const x = parseInt(args[0]);
149	                    const z = parseInt(args[1]);
150	                    if (!isNaN(x) && !isNaN(z)) {
151	                        this.engine?.teleportTo(x, z);
152	                    } else {
153	                        this.log('ERROR', 'Bridge', 'Invalid coordinates: /tp <x> <z>');
154	                    }
155	                } else {
156	                    this.log('ERROR', 'Bridge', 'Usage: /tp <x> <z>');
157	                }
158	                break;
159	
160	            case '/spawn':
161	                if (args.length >= 1) {
162	                    const id = parseInt(args[0]);
163	                    if (!isNaN(id)) {
164	                        this.engine?.spawnNPCCommand(id);
165	                    } else {
166	                        this.log('ERROR', 'Bridge', 'Invalid ID: /spawn <id>');
167	                    }
168	                } else {
169	                    this.log('ERROR', 'Bridge', 'Usage: /spawn <id>');
170	                }
171	                break;
172	
173	            case '/collision':
174	                const active = args[0] === 'on' || args[0] === '1' || args[0] === 'true';
175	                this.engine?.updateCollisionOverlay(active);
176	                break;
177	
178	            case '/export':
179	                this.log('INFO', 'Bridge', 'Manifesting POG2 Synthesis Export...');
180	                const manifest = {
181	                    timestamp: Date.now(),
182	                    chunks: this.engine?.spatialManager?.getIndexedChunkKeys() || [],
183	                    npcs: this.engine?.npcs?.map((n: any) => n.id) || []
184	                };
185	                console.log('[POG2 EXPORT]', manifest);
186	                this.log('INFO', 'Bridge', `Export Consolidated: ${manifest.chunks.length} Chunks, ${manifest.npcs.length} NPCs.`);
187	                break;
188	
189	            default:
190	                // Authoritative Admin Command Relay (Phase 29)
191	                if (command.startsWith('::')) {
192	                    const rawCmd = command.substring(2);
193	                    this.log('CMD', 'Admin', `Relaying Authoritative Trigger: ${rawCmd}`);
194	                    this.sendAction(JSON.stringify({ 
195	                        type: 'ADMIN_COMMAND', 
196	                        payload: {
197	                            command: rawCmd,
198	                            args: args,
199	                            timestamp: Date.now()
200	                        } 
201	                    }));
202	                } else {
203	                    // Relay unknown commands to the backend orchestrator
204	                    this.sendAction(JSON.stringify({ type: 'CONSOLE_COMMAND', payload: cmd }));
205	                }
206	                break;
207	        }
208	    }
209	
210	    /**
211	     * sendAction - Push a manual or autonomous action back to the backend.
212	     */
213	    public sendAction(intent: string) {
214	        if (this.ws?.readyState === WebSocket.OPEN) {
215	            this.ws.send(JSON.stringify({
216	                type: 'command',
217	                intent
218	            }));
219	        }
220	    }
221	
222	    /**
223	     * log - Relay a system event to all subscribers (Clinical HUD console).
224	     */
225	    public log(level: 'INFO' | 'WARN' | 'ERROR' | 'CMD', source: string, message: string) {
226	        const payload = { timestamp: Date.now(), level, source, message };
227	        this.notifyLogListeners(payload);
228	        
229	        // Optionally relay back to orchestrator if needed for forensic persistence
230	        if (this.ws?.readyState === WebSocket.OPEN) {
231	            this.ws.send(JSON.stringify({ type: 'SYSTEM_LOG', payload }));
232	        }
233	    }
234	}
