52	    setInterval(() => {
53	        const switchboard = SwitchboardLimb.getInstance();
54	        const tick = Date.now();
55	
56	        switchboard.broadcast({ type: 'tick_event', tick, events: [] });
57	
58	        // Synthesize a state_sync so SovereignHUD renders immediately.
59	        // When a real game session is active, gameState is populated by syncGameState();
